package cn.pawday;

import cn.pawday.identity.Crypto;
import io.zonky.test.db.postgres.embedded.EmbeddedPostgres;
import java.net.URI;
import java.net.http.*;
import java.nio.file.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
class V31ServiceBookingIntegrationTests {
 static final EmbeddedPostgres PG;
 static {try{PG=EmbeddedPostgres.builder().setPort(0).start();}catch(Exception e){throw new ExceptionInInitializerError(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->PG.getJdbcUrl("postgres","postgres"));r.add("spring.datasource.username",()->"postgres");r.add("spring.datasource.password",()->"postgres");r.add("pawday.auth.secret-key",()->"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=");for(String k:List.of("management.health.redis.enabled","management.health.rabbit.enabled","pawday.outbox.workers-enabled","pawday.outbox.consumer-enabled","pawday.search.enabled","pawday.storage.cleanup-enabled","pawday.checkout.expiry-enabled","pawday.ordering.expiry-enabled","pawday.payment.recovery-enabled","pawday.refund.recovery-enabled","pawday.settlement.worker-enabled"))r.add(k,()->false);r.add("pawday.booking.simulation-enabled",()->true);}
 @Autowired JdbcTemplate db;@Autowired Crypto crypto;@Autowired Clock clock;@LocalServerPort int port;
 final JsonMapper json=JsonMapper.builder().build();final HttpClient http=HttpClient.newHttpClient();
 static final List<Map<String,Object>> SAMPLES=new CopyOnWriteArrayList<>();
 UUID store,merchantId;String merchant,reader,user,other,foreign;
 record Response(int status,JsonNode body){JsonNode data(){return body.get("data");}String id(){return data().get("id").asString();}}
 String key(){return UUID.randomUUID().toString();}
 String identity(boolean consumer,UUID m,UUID st,List<String> permissions){UUID p=UUID.randomUUID(),role=UUID.randomUUID();String realm=consumer?"CONSUMER":"MERCHANT";
  if(consumer){UUID u=UUID.randomUUID();db.update("INSERT INTO app_user(id,status) VALUES (?,'ACTIVE')",u);db.update("INSERT INTO identity_principal(id,realm,user_id) VALUES (?,'CONSUMER',?)",p,u);}else db.update("INSERT INTO identity_principal(id,realm,merchant_id,login_name,password_hash) VALUES (?,'MERCHANT',?,?,?)",p,m,key(),"TEST-ONLY");
  db.update("INSERT INTO role(id,scope_type,code,name) VALUES (?,?,?,'BOOKING TEST')",role,realm,key());for(String code:permissions)db.update("INSERT INTO role_permission SELECT ?,id FROM permission WHERE code=?",role,code);db.update("INSERT INTO principal_role VALUES (?,?,?)",p,role,realm);
  if(!consumer)db.update("INSERT INTO principal_store_scope VALUES (?,?,?)",p,m,st);
  String token=crypto.token();db.update("INSERT INTO auth_session(id,principal_id,access_token_hash,device_id,expires_at,refresh_expires_at,created_at) VALUES (?,?,?,'BOOKING-IT',?,?,?)",UUID.randomUUID(),p,crypto.hash(token),Timestamp.from(clock.instant().plusSeconds(900)),Timestamp.from(clock.instant().plusSeconds(2592000)),Timestamp.from(clock.instant()));return token;
 }
 UUID store(UUID m){UUID s=UUID.randomUUID();db.update("INSERT INTO merchant_store(id,merchant_id,name) VALUES (?,?,'TEST booking store')",s,m);db.update("INSERT INTO nearby_store_profile(store_id,city,category,address,phone,business_hours,longitude,latitude,services,publication_status,claim_status) VALUES (?,'TEST','GROOMING','TEST address','123456','TEST hours',106,29,'[\"GROOMING\"]','PUBLISHED','VERIFIED')",s);return s;}
 @BeforeEach void setup(){merchantId=UUID.randomUUID();db.update("INSERT INTO merchant VALUES (?,'TEST booking merchant','ACTIVE')",merchantId);store=store(merchantId);merchant=identity(false,merchantId,store,List.of("store.read","store.nearby.write"));reader=identity(false,merchantId,store,List.of("store.read"));user=identity(true,null,null,List.of());other=identity(true,null,null,List.of());UUID m=UUID.randomUUID();db.update("INSERT INTO merchant VALUES (?,'TEST foreign','ACTIVE')",m);foreign=identity(false,m,store(m),List.of("store.read","store.nearby.write"));}
 Response req(String method,String path,Object body,String token,Map<String,String> headers){try{var builder=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1"+path)).timeout(Duration.ofSeconds(30));if(token!=null)builder.header("Authorization","Bearer "+token);headers.forEach(builder::header);builder.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)));if(body!=null)builder.header("Content-Type","application/json");var response=http.send(builder.build(),HttpResponse.BodyHandlers.ofString());var result=json.readTree(response.body());SAMPLES.add(Map.of("method",method.toLowerCase(),"path",path,"status",response.statusCode(),"response",result));return new Response(response.statusCode(),result);}catch(Exception e){throw new AssertionError(e);}}
 Response get(String path,String token){return req("GET",path,null,token,Map.of());}
 Response post(String path,Object b,String token){return req("POST",path,b,token,Map.of("Idempotency-Key",key()));}
 String services(){return "/merchant/stores/"+store+"/booking-services";}
 String create(){var r=post(services(),Map.of("title","TEST wash","kind","GROOMING"),merchant);assertEquals(200,r.status(),r.body().toString());return r.id();}
 Map<String,Object> interval(int seats){Instant start=clock.instant().plus(Duration.ofDays(2)).truncatedTo(java.time.temporal.ChronoUnit.SECONDS);return Map.of("starts_at",start.toString(),"ends_at",start.plusSeconds(3600).toString(),"capacity",seats);}
 String slot(String service,int seats){var r=post("/merchant/booking-services/"+service+"/slots",interval(seats),merchant);assertEquals(200,r.status(),r.body().toString());return r.id();}
 Response reserve(String slot,String who,String k){return req("POST","/consumer/service-bookings",Map.of("slot_id",slot),who,Map.of("Idempotency-Key",k));}
 Response cancel(String booking,String who,String k,long v){return req("POST","/consumer/service-bookings/"+booking+"/cancel",Map.of(),who,Map.of("Idempotency-Key",k,"If-Match","\""+v+"\""));}
 Response state(String service,String status,long v){return req("PUT","/merchant/booking-services/"+service+"/state",Map.of("status",status),merchant,Map.of("Idempotency-Key",key(),"If-Match","\""+v+"\""));}
 @Test void startedSlotsCannotBeBookedOrCancelledAndLongIntervalsAreInvalid(){String s=create();UUID slot=UUID.randomUUID(),booking=UUID.randomUUID();Instant start=clock.instant().minusSeconds(1);db.update("INSERT INTO booking_slots(id,service_id,starts_at,ends_at,capacity) VALUES (?,?,?,?,2)",slot,UUID.fromString(s),Timestamp.from(start),Timestamp.from(start.plusSeconds(3600)));UUID uid=db.queryForObject("SELECT p.user_id FROM identity_principal p JOIN auth_session a ON a.principal_id=p.id WHERE a.access_token_hash=?",UUID.class,crypto.hash(user));db.update("INSERT INTO service_bookings(id,slot_id,service_id,store_id,user_id,service_title) VALUES (?,?,?,?,?,'TEST past')",booking,slot,UUID.fromString(s),store,uid);assertEquals(409,reserve(slot.toString(),other,key()).status());assertEquals(409,cancel(booking.toString(),user,key(),0).status());var interval=new HashMap<>(interval(1));interval.put("ends_at",Instant.parse(interval.get("starts_at").toString()).plus(Duration.ofDays(8)).toString());assertEquals(400,post("/merchant/booking-services/"+s+"/slots",interval,merchant).status());}
 @Test void concurrentSameCommandCreatesOnlyOneBooking()throws Exception{String slot=slot(create(),2),k=key();try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var first=pool.submit(()->reserve(slot,user,k));var second=pool.submit(()->reserve(slot,user,k));var a=first.get();var b=second.get();assertEquals(200,a.status());assertEquals(200,b.status());assertEquals(a.id(),b.id());}assertEquals(1,db.queryForObject("SELECT count(*) FROM service_bookings WHERE slot_id=?",Integer.class,UUID.fromString(slot)));}
 @AfterAll static void samples()throws Exception{Path p=Path.of("target/v31-contract-samples.json");Files.createDirectories(p.getParent());Files.writeString(p,JsonMapper.builder().build().writeValueAsString(SAMPLES));}

 @Test void bookingCancellationReleasesCapacityAndReplaysWithoutCharging(){String s=create(),slot=slot(s,1),k=key();var booked=reserve(slot,user,k);assertEquals(200,booked.status(),booked.body().toString());assertEquals(booked.body().get("data"),reserve(slot,user,k).data());assertTrue(booked.data().get("simulated").asBoolean());assertEquals(0,booked.data().get("amount_fen").asInt());assertEquals(409,reserve(slot,other,key()).status());String cancelKey=key();assertEquals(200,cancel(booked.id(),user,cancelKey,0).status());assertEquals(200,cancel(booked.id(),user,cancelKey,0).status());assertEquals(200,reserve(slot,other,key()).status());assertEquals(1,db.queryForObject("SELECT count(*) FROM service_bookings WHERE slot_id=? AND status='BOOKED'",Integer.class,UUID.fromString(slot)));assertEquals(0,db.queryForObject("SELECT count(*) FROM payments",Integer.class));}
 @Test void concurrentConsumersCannotOversellLastSeat()throws Exception{String slot=slot(create(),1);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var latch=new CountDownLatch(1);var a=pool.submit(()->{latch.await();return reserve(slot,user,key());});var b=pool.submit(()->{latch.await();return reserve(slot,other,key());});latch.countDown();var statuses=new ArrayList<>(List.of(a.get().status(),b.get().status()));Collections.sort(statuses);assertEquals(List.of(200,409),statuses);}assertEquals(1,db.queryForObject("SELECT count(*) FROM service_bookings WHERE slot_id=? AND status='BOOKED'",Integer.class,UUID.fromString(slot)));}
 @Test void ownershipRealmAndRevokedStoreScope(){String s=create(),slot=slot(s,2);var b=reserve(slot,user,key());assertEquals(401,get(services(),null).status());assertEquals(403,get(services(),user).status());assertEquals(404,get(services(),foreign).status());assertEquals(403,post(services(),Map.of("title","NO","kind","GROOMING"),reader).status());assertEquals(404,cancel(b.id(),other,key(),0).status());assertEquals(0,get("/consumer/service-bookings",other).data().size());assertEquals(200,get("/consumer/service-bookings",user).status());assertEquals(200,get("/merchant/stores/"+store+"/service-bookings",merchant).status());assertEquals(200,get("/merchant/booking-services/"+s+"/slots",merchant).status());assertEquals(200,get(services(),reader).status());db.update("DELETE FROM principal_store_scope WHERE store_id=? AND principal_id IN (SELECT principal_id FROM auth_session WHERE access_token_hash=?)",store,crypto.hash(merchant));assertEquals(404,get(services(),merchant).status());}
 @Test void hiddenStorePausedServiceAndSuspendedMerchantBlockNewReservationsButNotOwnCancellation(){String s=create(),slot=slot(s,2);var b=reserve(slot,user,key());assertEquals(200,state(s,"PAUSED",0).status());assertEquals(409,reserve(slot,other,key()).status());assertEquals(404,get("/consumer/booking-services/"+s+"/slots",user).status());assertEquals(200,state(s,"ACTIVE",1).status());db.update("UPDATE nearby_store_profile SET publication_status='HIDDEN' WHERE store_id=?",store);assertEquals(404,reserve(slot,other,key()).status());assertEquals(200,cancel(b.id(),user,key(),0).status());db.update("UPDATE nearby_store_profile SET publication_status='PUBLISHED' WHERE store_id=?",store);db.update("UPDATE merchant SET status='SUSPENDED' WHERE id=?",merchantId);assertEquals(404,get("/consumer/stores/"+store+"/booking-services",user).status());}
 @Test void overlappingIntervalsAndInvalidInputsAreRejected(){String s=create();slot(s,2);assertEquals(409,post("/merchant/booking-services/"+s+"/slots",interval(2),merchant).status());assertEquals(400,post(services(),Map.of("title","TEST","kind","MEDICAL"),merchant).status());assertEquals(400,post(services(),Map.of("title","TEST","kind","GROOMING","price_fen",1),merchant).status());var invalid=new HashMap<>(interval(0));assertEquals(400,post("/merchant/booking-services/"+s+"/slots",invalid,merchant).status());invalid.put("capacity",1);invalid.put("starts_at",clock.instant().minusSeconds(3600).toString());assertEquals(400,post("/merchant/booking-services/"+s+"/slots",invalid,merchant).status());assertEquals(400,get(services()+"?limit=101",merchant).status());assertEquals(400,req("POST",services(),Map.of("title","TEST","kind","GROOMING"),merchant,Map.of()).status());}
 @Test void changedPayloadDuplicateBookingStaleVersionAndImmutableFacts(){String s=create(),slot=slot(s,2),k=key();var b=reserve(slot,user,k);assertEquals(409,reserve(slot,user,key()).status());String another=slot(create(),1);assertEquals(409,reserve(another,user,k).status());assertEquals(409,cancel(b.id(),user,key(),99).status());assertEquals(200,state(s,"PAUSED",0).status());assertEquals(409,state(s,"ACTIVE",0).status());assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE service_bookings SET amount_fen=1 WHERE id=?",UUID.fromString(b.id())));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE booking_slots SET capacity=3 WHERE id=?",UUID.fromString(slot)));String path="/merchant/stores/"+store+"/service-bookings/"+b.id()+"/cancel";assertEquals(200,req("POST",path,Map.of(),merchant,Map.of("Idempotency-Key",key(),"If-Match","\"0\"")).status());assertEquals(409,cancel(b.id(),user,key(),1).status());}
 @Test void consumerListsArePaginatedAndDoNotExposeOtherCustomerIdentifiers(){String s=create();slot(s,1);create();var first=get("/consumer/stores/"+store+"/booking-services?limit=1",user);assertEquals(1,first.data().size());assertTrue(first.body().get("page").get("has_more").asBoolean());assertEquals(1,get("/consumer/stores/"+store+"/booking-services?limit=1&cursor="+first.body().get("page").get("next_cursor").asString(),user).data().size());var slots=get("/consumer/booking-services/"+s+"/slots",user);assertEquals(1,slots.data().get(0).get("remaining").asInt());reserve(slots.data().get(0).get("id").asString(),user,key());var list=get("/merchant/stores/"+store+"/service-bookings",merchant);assertFalse(list.body().toString().contains("user_id"));assertFalse(list.body().toString().contains("phone"));assertFalse(list.body().toString().contains("cancelled_by"));}
}
